// A package inventory produced this report. Plain data — it carries no output formatting.

var pkg = new PackageReport
{
    Id = "Serilog",
    Downloads = 500_000_000,
    Dependencies = new()
    {
        new() { Name = "Serilog.Sinks.Console", Version = "5.0.0" },
    },
    Tags = new() { "logging", "structured" },
};

// One model, two reports. The detail sections are gated on the Verbose flag,
// so quiet output drops them and verbose output includes them.

Console.WriteLine("=== quiet ===");
pkg.Verbose = false;
MarkoutSerializer.Serialize(pkg, Console.Out, PackageReportContext.Default);

Console.WriteLine();
Console.WriteLine("=== verbose ===");
pkg.Verbose = true;
MarkoutSerializer.Serialize(pkg, Console.Out, PackageReportContext.Default);

[MarkoutSerializable(TitleProperty = nameof(Id))]
public sealed class PackageReport
{
    public string Id { get; init; } = "";
    public long Downloads { get; init; }

    [MarkoutIgnore]
    public bool Verbose { get; set; }

    [MarkoutSection(Name = "Dependencies")]
    [MarkoutShowWhen(nameof(Verbose))]
    public List<Dep> Dependencies { get; init; } = new();

    [MarkoutSection(Name = "Tags")]
    [MarkoutShowWhen(nameof(Verbose))]
    public List<string> Tags { get; init; } = new();
}

[MarkoutSerializable]
public sealed class Dep { public string Name { get; init; } = ""; public string Version { get; init; } = ""; }

[MarkoutContext(typeof(PackageReport))]
[MarkoutContext(typeof(Dep))]
public partial class PackageReportContext : MarkoutSerializerContext { }
"}

