// One model definition; the rendered sections are chosen at serialize time via IncludeSections.
Render("QUIET", []);
Render("NORMAL", ["Dependencies"]);
Render("DETAILED", ["Dependencies", "Diagnostics"]);

void Render(string label, string[] sections)
{
    var options = new MarkoutWriterOptions { IncludeSections = new(sections) };
    Console.WriteLine($"===== {label} =====");
    MarkoutSerializer.Serialize(pkg, Console.Out, PackageReportContext.Default, options);
    Console.WriteLine();
}

