// One model definition (PackageReport) drives three renders. Two knobs are kept separate:
//   * Verbosity  — how much (expensive) detail we COLLECT into the model.
//   * IncludeSections — which collected sections we RENDER at serialize time.

using Markout;

var reports = new (string Label, Verbosity Requested, string[] Target)[]
{
    // 1. Quiet: title + scalars only. Nothing beyond scalars is collected or rendered.
    ("Quiet",       Verbosity.Quiet, Array.Empty<string>()),

    // 2. Target ONLY the Diagnostics section by name. Diagnostics is the deepest/most
    //    expensive detail, so naming it PROMOTES the effective verbosity to Diagnostic —
    //    enough to collect it — yet we render Diagnostics and NOT Dependencies.
    ("Diagnostics", Verbosity.Quiet, new[] { "Diagnostics" }),

    // 3. Detailed: collect and render both detail sections.
    ("Detailed",    Verbosity.Detailed, new[] { "Dependencies", "Diagnostics" }),
};

foreach (var (label, requested, target) in reports)
{
    var effective = EffectiveVerbosity(requested, target);
    var report = Collect(effective);

    // Render-time selection: empty set renders no sections; a populated set renders only
    // the named sections. Omitted sections are never hand-written.
    var options = new MarkoutWriterOptions { IncludeSections = new HashSet<string>(target) };

    Console.WriteLine($"<!-- {label}: requested={requested}, effective={effective} -->");
    MarkoutSerializer.Serialize(report, Console.Out, ReportContext.Default, options);
    Console.WriteLine();
}

// Naming a section promotes the effective verbosity to at least that section's floor,
// guaranteeing its (expensive) data is collected before we try to render it.
static Verbosity EffectiveVerbosity(Verbosity requested, IEnumerable<string> target)
{
    var effective = requested;
    foreach (var section in target)
        if (SectionFloor.TryGetValue(section, out var floor) && floor > effective)
            effective = floor;
    return effective;
}

// Collect only the detail the effective verbosity pays for. Diagnostics is deepest/most
// expensive, so it is gathered last and only at the Diagnostic level.
static PackageReport Collect(Verbosity verbosity) => new()
{
    Id = "Serilog",
    Downloads = 500_000_000,
    Dependencies = verbosity >= Verbosity.Detailed
        ? new() { new() { Name = "Serilog.Sinks.Console", Version = "5.0.0" } }
        : new(),
    Diagnostics = verbosity >= Verbosity.Diagnostic
        ? new() { new() { Level = "warning", Text = "transitive version conflict" } }
        : new(),
};

static readonly Dictionary<string, Verbosity> SectionFloor = new()
{
    ["Dependencies"] = Verbosity.Detailed,
    ["Diagnostics"] = Verbosity.Diagnostic,
};

// Deeper = more detail, and more collection cost.
public enum Verbosity { Quiet = 0, Detailed = 1, Diagnostic = 2 }

[MarkoutSerializable(TitleProperty = nameof(Id))]
public sealed class PackageReport
{
    public string Id { get; init; } = "";
    public long Downloads { get; init; }

    [MarkoutSection(Name = "Dependencies")]
