    ("Diagnostics", Verbosity.Quiet, new[] { "Diagnostics" }),

    // 3. Detailed: collect and render both detail sections.
    ("Detailed",    Verbosity.Detailed, new[] { "Dependencies", "Diagnostics" }),
};

